    tryCatch(
      {
        x <- getSummariseObservationPeriodPlot()
        renderInteractivePlot(x, input$summarise_observation_period_plot_interactive)
      },
      error = function(e) {
        if (inherits(e, "shiny.silent.error")) stop(e)
        shiny::div(class = "alert alert-danger text-white d-flex align-items-start gap-2", shiny::icon("triangle-exclamation", class = "mt-1"), shiny::div(class = "error-message", conditionMessage(e)))
      }
    )
  })
  output$summarise_observation_period_plot_download <- shiny::downloadHandler(
    filename = "plot_observation_period.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
